--
-- Table structure for table `route_master_outlet`
--

DROP TABLE IF EXISTS `route_master_outlet`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `route_master_outlet` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `route_master_id` bigint NOT NULL,
  `customer_id` bigint NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `visit_order` int DEFAULT NULL,
  `monday` tinyint(1) NOT NULL DEFAULT '0',
  `tuesday` tinyint(1) NOT NULL DEFAULT '0',
  `wednesday` tinyint(1) NOT NULL DEFAULT '0',
  `thursday` tinyint(1) NOT NULL DEFAULT '0',
  `friday` tinyint(1) NOT NULL DEFAULT '0',
  `saturday` tinyint(1) NOT NULL DEFAULT '0',
  `sunday` tinyint(1) NOT NULL DEFAULT '0',
  `visit_weeks` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_route_master_outlet` (`route_master_id`,`customer_id`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `route_master_outlet_ibfk_1` FOREIGN KEY (`route_master_id`) REFERENCES `route_master` (`id`),
  CONSTRAINT `route_master_outlet_ibfk_2` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=523 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

